ValidationRule.errorConditionFormula:
AND (
ISPICKVAL(StageName, "Recalendarización"), ISPICKVAL(Cliente_Acepta_oferta__c, "NO"), ISPICKVAL(Siguientes_pasos__c, "Cliente no acepta propuesta y desea que se le de seguimiento posteriormente"), ISBLANK( Fecha_de_seguimiento__c), RecordType.Name = "Patrimonial" ) || AND( ISPICKVAL(StageName, "Recalendarización"), ISCHANGED(StageName), ISBLANK( Fecha_de_seguimiento__c), RecordType.Name = "Patrimonial"
)
